#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_1TO1_NAT FW_PORTFORWARDING FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_ip_nat_3_src && fail 'an IP group named fws_ip_nat_3_src exists; nothing was written'
named FW_GROUP_IP fws_firewall_1_src && fail 'an IP group named fws_firewall_1_src exists; nothing was written'
named FW_GROUP_IP fws_firewall_3_dst && fail 'an IP group named fws_firewall_3_dst exists; nothing was written'
named FW_GROUP_IP fws_firewall_8_dst && fail 'an IP group named fws_firewall_8_dst exists; nothing was written'
named FW_GROUP_IP fws_firewall_9_src && fail 'an IP group named fws_firewall_9_src exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_ip_nat_3_src --set .COMMENT 'FWShift: 192.168.127.1-192.168.127.199'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.127.1-192.168.127.199
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_firewall_1_src --set .COMMENT 'FWShift: 192.168.127.10-192.168.127.20'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.127.10-192.168.127.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_firewall_3_dst --set .COMMENT 'FWShift: 192.168.127.50, wan1-address'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.127.50
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.2
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_firewall_8_dst --set .COMMENT 'FWShift: 192.168.127.60-192.168.127.69'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.127.60-192.168.127.69
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_firewall_9_src --set .COMMENT 'FWShift: 192.168.127.200-192.168.127.250'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.127.200-192.168.127.250
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 23 --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'firewall 2'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 198.51.100.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'firewall 3'
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_firewall_3_dst
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext2 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 192.168.127.60 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'firewall 10'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF all --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO icmp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'firewall 5'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'firewall 9'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_firewall_9_src
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 192.168.127.60 --set .REMOTE_NET 198.51.100.60 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT 'ip nat 2: ip nat static inside lan 192.168.127.60 outside wan 2 198.51.100.60'
N=$((N+1))

# FW_PORTFORWARDING
N=$(rows FW_PORTFORWARDING)
gc --silent --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP 203.0.113.2 --set .IN_PORT 8443 --set .OUT_IP 192.168.127.50 --set .OUT_PORT 443 --set .LOG no --set .COMMENT 'ip nat 1: ip nat static tcp inside lan 192.168.127.50 443 outside wan 1 8443'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --silent --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 0.0.0.0/32 --set .COMMENT 'ip nat 3: ip nat dynamic inside lan 192.168.127.1 192.168.127.199 outside wan 1'
gc --set-refname "FW_NAT.$N.IN_IP" fws_ip_nat_3_src
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
